target.css:
:root {
  --ink: #142b3d;
  --muted: #637989;
  --paper: #ffffff;
  --ice: #eaf7fa;
  --frost: #c8e9ee;
  --line: #b9dce2;
  --navy: #164967;
  --aqua: #14a6af;
  --mint: #d9f4e8;
  --mint-ink: #167052;
  --coral: #e87562;
}

* {
  box-sizing: border-box;
}

.core-panel {
  width: 488px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 15px 18px 13px;
  border-bottom: 1px solid var(--line);
}

.title-block p,
.title-block h1,
.transfer-heading p,
.panel-footer p,
.core-figure figcaption {
  margin: 0;
}

.eyebrow,
.section-label {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.1px;
  line-height: 1.2;
}

.title-block h1 {
  margin-top: 4px;
  color: var(--navy);
  font-size: 21px;
  font-weight: 750;
  line-height: 1.05;
}

.verified {
  border: 0;
  border-radius: 999px;
  padding: 7px 10px;
  background: var(--mint);
  color: var(--mint-ink);
  font-size: 11px;
  font-weight: 700;
}

.panel-main {
  display: grid;
  grid-template-columns: 132px 1fr;
  gap: 16px;
  padding: 15px 18px;
  background: var(--ice);
}

.core-figure {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 136px;
  margin: 0;
  border: 1px solid var(--frost);
  border-radius: 14px;
  background: var(--paper);
  text-align: center;
}

.core-mark {
  display: grid;
  width: 48px;
  height: 48px;
  place-items: center;
  border: 6px solid var(--aqua);
  border-radius: 50%;
  color: var(--navy);
  font-size: 13px;
  font-weight: 800;
  letter-spacing: .5px;
}

.core-figure figcaption {
  margin-top: 8px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.35;
}

.core-figure strong {
  color: var(--navy);
  font-size: 13px;
}

.details {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-width: 0;
}

.transfer-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  padding-bottom: 9px;
  border-bottom: 1px solid var(--line);
}

.transfer-heading strong {
  color: var(--navy);
  font-size: 15px;
  line-height: 1;
}

.readings {
  display: grid;
  gap: 5px;
  margin: 9px 0 0;
  padding: 0;
  list-style: none;
}

.readings li {
  display: flex;
  justify-content: space-between;
  padding: 3px 0;
  color: var(--muted);
  font-size: 12px;
}

.readings strong {
  color: var(--ink);
  font-size: 12px;
}

.panel-footer {
  display: flex;
  justify-content: space-between;
  padding: 10px 18px;
  background: var(--navy);
  color: var(--frost);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .25px;
}

.panel-footer p:first-child {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--paper);
}

.pulse {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--coral);
}

